export const INKS = {
  blue: "#4169e1",
  red: "#fa594b",
  graphite: "#444440",
  green: "#4f9778",
};

function movingPeoplePath(definition, geometry, figure, now, resumedAt) {
  geometry.vertices ??= [...definition.ink.matchAll(/([ML])\s+(-?[\d.]+)\s+(-?[\d.]+)|(Z)/g)]
    .map(match => match[4] ? ["Z"] : [match[1], Number(match[2]), Number(match[3])]);
  const conversation = definition.name === "seated-conversation";
  const person = { ...figure, kind: "person" };
  const motions = Array.from({ length: conversation ? 3 : 1 }, (_, i) => idleMotion(person, "seated", now, resumedAt, i));
  const path = new Path2D();
  for (const [command, x, y] of geometry.vertices) {
    if (command === "Z") { path.closePath(); continue; }
    let dx, dy;
    if (conversation) {
      // Let the three seated people breathe independently, blending at their
      // shared hands so the source contours stay connected without clip seams.
      const position = Math.max(0, Math.min(2, (x / definition.width + 0.5) * 3 - 0.5));
      const i = Math.floor(position), t = position - i;
      const a = motions[i], b = motions[Math.min(2, i + 1)];
      dx = y * (a.lean + (b.lean - a.lean) * t);
      dy = y * (a.breath - 1 + (b.breath - a.breath) * t);
    } else {
      // Animate the reader above the tabletop, leaving the furniture fixed.
      const height = Math.min(0, y + 48);
      const weight = Math.min(1, -height / 16);
      dx = height * motions[0].lean * weight;
      dy = height * (motions[0].breath - 1) * weight;
    }
    if (command === "M") path.moveTo(x + dx, y + dy);
    else path.lineTo(x + dx, y + dy);
  }
  return path;
}

export function drawFigure(ctx, figure, paths, progress = 1, now, resumedAt) {
  if (progress <= 0) return;
  const definition = (figure.kind === "object" ? OBJECTS : FIGURES)[figure.index];
  let geometry = paths.get(definition);
  if (!geometry) {
    geometry = { ink: new Path2D(definition.ink), trace: planTrace(definition.ink) };
    paths.set(definition, geometry);
  }
  ctx.save();
  ctx.translate(figure.x, figure.y);
  ctx.scale(figure.flip * figure.scale, figure.scale);
  let ink = geometry.ink;
  if (progress >= 1 && now !== undefined) {
    if (["seated-conversation", "reading-at-a-table"].includes(definition.name)) {
      ink = movingPeoplePath(definition, geometry, figure, now, resumedAt);
    } else {
      const movement = idleMotion(figure, definition.pose, now, resumedAt);
      // Shear and breathe around y=0 so the feet never leave their ground.
      ctx.transform(1, 0, movement.lean, movement.breath, 0, 0);
    }
  }
  if (progress < 1) ctx.clip(traceMask(geometry.trace, progress));
  ctx.fillStyle = figure.ink;
  ctx.fill(ink, "evenodd");
  ctx.restore();
}
